/**
 * Legacy ESLint config, for ESLint 8 / `@wordpress/scripts` below 32.
 *
 * Generated by `bin/update-configs`. The rules live in wporg-repo-tools and
 * arrive with `composer update` — edit them there, not here.
 *
 * Project-specific rules go inside the `rules` object below, alongside the
 * spread of the shared ones. Do not add a second `rules` key after the spread
 * of `config`: this format merges shallowly, so that would replace every
 * shared rule at once, silently and without failing the lint.
 */

/**
 * Internal dependencies
 */
const createConfig = require( './vendor/wporg/wporg-repo-tools/configs/eslintrc' );

const config = createConfig( {
	textDomain: '${TEXTDOMAIN}',
	prettierConfig: require( './.prettierrc' ),
} );

module.exports = {
	...config,
	rules: {
		...config.rules,
	},
};
